solution:
#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int dung = 0;
    for (int i = 1; i <= n; i++) {
        int x;
        scanf("%d", &x);
        if (x == i) dung++;
    }
    printf("%d\n", dung);
    return 0;
}

