#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int a[100];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int sai = 0;
    for (int i = 0; i + 1 < n; i++) {
        if (a[i] > a[i + 1]) sai++;
    }
    printf("%d\n", sai);
    return 0;
}

