#include <stdio.h>

int main(void) {
    int n, m;
    scanf("%d", &n);
    int dat = 1;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x != 1) dat = 0;
    }
    scanf("%d", &m);
    if (dat && m == 0) printf("dat\n");
    else printf("chua dat\n");
    return 0;
}
